import c from"./BaseSegment.js";import{Vec3 as h}from"../../math/Vec3.js";import{T_VALUES as z,C_VALUES as o}from"./utils.js";const l=new h;function p(s,e,t,n){const i=1-s;return i*i*e+2*i*s*t+s*s*n}function a(s,e,t,n){return 2*(1-s)*(t-e)+2*s*(n-t)}class m extends c{constructor(e,t,n,i=0,r=0){super(),this.p0=e,this.p1=t,this.p2=n,this.tiltStart=i,this.tiltEnd=r,this._len=-1}updateLength(){const t=z.length;let n=0;for(let i=0,r;i<t;i++)r=.5*z[i]+.5,n+=o[i]*this.getDerivativeAt(r,l).len();this._len=.5*n}getPointAt(e,t=new h){return t.x=p(e,this.p0.x,this.p1.x,this.p2.x),t.y=p(e,this.p0.y,this.p1.y,this.p2.y),t.z=p(e,this.p0.z,this.p1.z,this.p2.z),t}getDerivativeAt(e,t=new h){return t.x=a(e,this.p0.x,this.p1.x,this.p2.x),t.y=a(e,this.p0.y,this.p1.y,this.p2.y),t.z=a(e,this.p0.z,this.p1.z,this.p2.z),t}getTangentAt(e,t=new h){return this.getDerivativeAt(e,t).normalize()}lastPoint(){return this.p2}}export{m as default};
